<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'factures.view')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_sales.php';
$db=Database::getInstance();$role=$user['role_system'];$search=trim((string)($_GET['q']??''));$from=(string)($_GET['du']??'');$to=(string)($_GET['au']??'');
$conditions=["document_type = 'Facture'", "origin = 'Vente comptoir'", "status = 'Active'"];$params=[];
if($search!==''){$conditions[]='(invoice_number LIKE ? OR client_name LIKE ? OR phone LIKE ?)';$p='%'.$search.'%';array_push($params,$p,$p,$p);}
if($from!==''&&receptionValidDate($from)){$conditions[]='date >= ?';$params[]=$from;}else{$from='';}
if($to!==''&&receptionValidDate($to)){$conditions[]='date <= ?';$params[]=$to;}else{$to='';}
$where='WHERE '.implode(' AND ',$conditions);$total=(int)$db->fetchColumn("SELECT COUNT(*) FROM sales $where",$params);$page=max(1,(int)($_GET['page']??1));$perPage=20;$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$invoices=$db->fetchAll("SELECT id,invoice_number,client_name,phone,date,tot_htva,tva,total_amount,netcash,payment_method,debt FROM sales $where ORDER BY date DESC,id DESC LIMIT $perPage OFFSET $offset",$params);
$flash=$_SESSION['flash_message']??null;unset($_SESSION['flash_message']);$pageUrl=static fn(int $target):string=>app_route_url('ventes/factures',$role).'?'.http_build_query(['q'=>$search,'du'=>$from,'au'=>$to,'page'=>$target]);
?>
<section class="space-y-5"><header class="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-semibold text-green-800">Ventes au comptoir</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Factures de vente</h1><p class="mt-1 text-sm text-slate-600"><?=number_format($total,0,',',' ')?> facture(s)</p></div><?php if(userCan($user,'ventes.create')):?><a href="<?=receptionEscape(app_route_url('ventes/nouvelle'))?>" class="rounded-md bg-green-700 px-4 py-2.5 text-sm font-semibold text-white">Nouvelle vente</a><?php endif;?></header>
<?php if($flash):?><div role="status" class="rounded-md border border-green-200 bg-green-50 px-4 py-3 text-sm text-green-800"><?=receptionEscape($flash['text']??'')?></div><?php endif;?>
<form method="get" action="<?=receptionEscape(app_url('router.php'))?>" class="grid gap-3 rounded-md border bg-white p-4 sm:grid-cols-2 xl:grid-cols-[1fr_auto_auto_auto_auto] xl:items-end"><input type="hidden" name="route" value="<?=receptionEscape($role.'/ventes/factures')?>"><label class="space-y-1 text-sm font-medium">Recherche<input name="q" value="<?=receptionEscape($search)?>" placeholder="Facture, client, téléphone" class="w-full rounded-md border px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium">Du<input type="date" name="du" value="<?=receptionEscape($from)?>" class="w-full rounded-md border px-3 py-2 font-normal"></label><label class="space-y-1 text-sm font-medium">Au<input type="date" name="au" value="<?=receptionEscape($to)?>" class="w-full rounded-md border px-3 py-2 font-normal"></label><button class="rounded-md border px-4 py-2 text-sm">Filtrer</button><?php if($search!==''||$from!==''||$to!==''):?><a href="<?=receptionEscape(app_route_url('ventes/factures'))?>" class="px-3 py-2 text-sm text-slate-600">Effacer</a><?php endif;?></form>
<div class="overflow-x-auto rounded-md border bg-white"><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Facture</th><th class="px-4 py-3">Client</th><th class="px-4 py-3">Date</th><th class="px-4 py-3">Paiement</th><th class="px-4 py-3 text-right">Total</th><th class="px-4 py-3 text-right">Reste dû</th><th class="px-4 py-3">Action</th></tr></thead><tbody class="divide-y"><?php if(!$invoices):?><tr><td colspan="7" class="px-4 py-12 text-center text-slate-500">Aucune facture de vente sur cette période.</td></tr><?php else:foreach($invoices as $invoice):?><tr class="hover:bg-slate-50"><td class="px-4 py-3 font-mono text-xs font-semibold"><?=receptionEscape($invoice['invoice_number'])?></td><td class="px-4 py-3"><div class="font-medium"><?=receptionEscape($invoice['client_name'])?></div><div class="text-xs text-slate-500"><?=receptionEscape($invoice['phone']?:'')?></div></td><td class="px-4 py-3"><?=receptionEscape(date('d/m/Y',strtotime($invoice['date'])))?></td><td class="px-4 py-3"><?=receptionEscape($invoice['payment_method'])?></td><td class="px-4 py-3 text-right font-semibold"><?=number_format((float)$invoice['total_amount'],0,',',' ')?> FBu</td><td class="px-4 py-3 text-right <?= (float)$invoice['debt']>0?'font-semibold text-rose-700':'text-slate-500' ?>"><?=number_format((float)$invoice['debt'],0,',',' ')?> FBu</td><td class="px-4 py-3"><a href="<?=receptionEscape(app_route_url('ventes/facture'))?>?id=<?=(int)$invoice['id']?>" class="inline-flex items-center gap-1 text-sm font-medium text-green-800 hover:underline"><i data-feather="file-text" class="h-4 w-4"></i> Facture</a></td></tr><?php endforeach;endif;?></tbody></table></div>
<?php if($pages>1):?><nav class="flex items-center justify-between"><span class="text-sm text-slate-600">Page <?=$page?> sur <?=$pages?></span><div class="flex gap-2"><?php if($page>1):?><a class="rounded border px-3 py-2 text-sm" href="<?=receptionEscape($pageUrl($page-1))?>">Précédent</a><?php endif;?><?php if($page<$pages):?><a class="rounded border px-3 py-2 text-sm" href="<?=receptionEscape($pageUrl($page+1))?>">Suivant</a><?php endif;?></div></nav><?php endif;?></section>